package com.training.arrays;

public class UpPyramid {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println();
		int n2 = 5;
		
		for(int i = 1; i <= n2; i++) {
			for(int j = 1;j <= i; j++) {
				
				System.out.print("*");
				
			}
			System.out.println();
			
		}

		
	}

}
